    }


def _array_diagnostic(length: int | None, base: dict, components) -> dict:
    """包装一层数组诊断；components 透传链底 tuple 的子诊断或 None。"""
    suffix = "[]" if length is None else f"[{length}]"
    return {
        "canonical": base["canonical"] + suffix,
        "kind": "array",
        # 动态数组本身动态；定长数组在元素动态时同样动态。
        "isDynamic": length is None or base["isDynamic"],
        "arrayLength": length,
        "base": base,
        "components": components,
    }

